import { Component } from '@angular/core';
import { Sort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { Router } from '@angular/router';
import {
  DataService,
  pageSelection,
  apiResultFormat,
  routes,
  SidebarService,
} from 'src/app/core/core.index';
import { donation, DonationCondition } from 'src/app/shared/model/page.model';
import { PaginationService, tablePageSize } from 'src/app/shared/shared.index';

import {
  FormBuilder,
  FormGroup,
  Validators,
  FormControl,
} from '@angular/forms';

declare var bootstrap: any;
interface data {
  value: string;
}
@Component({
  selector: 'app-sales-list',
  templateUrl: './sales-list.component.html',
  styleUrl: './sales-list.component.scss',
})
export class SalesListComponent {
  initChecked = false;
  public selectedValue1 = '';
  public selectedValue2 = '';
  public selectedValue3 = '';
  public selectedValue4 = '';
  public selectedValue5 = '';
  public selectedValue6 = '';
  public selectedValue7 = '';
  public selectedValue8 = '';
  public selectedValue9 = '';
  public selectedValue10 = '';
  public selectedValue11 = '';
  public selectedValue12 = '';
  public routes = routes;

  selectedList1: data[] = [
    { value: 'Sort by Date' },
    { value: '07 09 23' },
    { value: '21 09 23' },
  ];
  selectedList2: data[] = [
    { value: 'Choose Customer Name' },
    { value: 'Macbook pro' },
    { value: 'Orange' },
  ];
  selectedList3: data[] = [
    { value: 'Choose Status' },
    { value: 'Computers' },
    { value: 'Fruits' },
  ];
  selectedList4: data[] = [
    { value: 'Choose Payment Status' },
    { value: 'Computers' },
    { value: 'Fruits' },
  ];
  selectedList5: data[] = [{ value: 'Choose' }, { value: 'Customer Name' }];
  selectedList6: data[] = [{ value: 'Choose' }, { value: 'Supplier Name' }];
  selectedList7: data[] = [
    { value: 'Choose' },
    { value: 'Completed' },
    { value: 'Inprogress' },
  ];
  selectedList8: data[] = [{ value: 'Thomas' }, { value: 'Name' }];
  selectedList9: data[] = [
    { value: 'Dazzle Shoes' },
    { value: 'Supplier Name' },
  ];
  selectedList10: data[] = [
    { value: 'Choose' },
    { value: 'Completed' },
    { value: 'Inprogress' },
  ];
  selectedList11: data[] = [
    { value: 'Choose' },
    { value: 'Online' },
    { value: 'Cash' },
  ];
  selectedList12: data[] = [
    { value: 'Cash' },
    { value: 'Online' },
    { value: 'Inprogress' },
  ];
  conditionOptions: { condition_id: number; condition: string }[] = [];
  conditionStatusOptions: { value: string }[] = [
    { value: 'PENDING' },
    { value: 'APPROVED' },
    { value: 'UPGRADED' },
    { value: 'DOWNGRADED' },
  ];
  statusOptions: { value: string }[] = [
    { value: 'Pickup Pending Scheduling' },
    { value: 'Pickup Scheduled' },
    { value: 'Pickup Agent Assigned' },
    { value: 'Agent Out for Collection' },
    { value: 'Items Collected' },
    { value: 'Pickup Completed' },
    { value: 'Pickup Failed' },
    { value: 'Pickup Cancelled' },
  ];
  // pagination variables
  public tableData: Array<donation> = [];
  public singleDonation: donation = {} as donation;
  public pageSize = 10;
  public serialNumberArray: Array<number> = [];
  public totalData = 0;
  showFilter = false;
  dataSource!: MatTableDataSource<donation>;
  public searchDataValue = '';
  //** / pagination variables
  expandedIndex: number | null = null;
  statusForm!: FormGroup;
  showScheduledDate = false;
  conditionsForm!: FormGroup;
  selectedPickupStatusFilter: number = 0;
  constructor(
    private data: DataService,
    private pagination: PaginationService,
    private router: Router,
    private sidebar: SidebarService,
    private fb: FormBuilder
  ) {
    this.statusForm = this.fb.group({
      status: ['', Validators.required],
      notes: ['', Validators.required],
      scheduled_date: [''],
    });
    this.conditionsForm = this.fb.group({
      description: ['', Validators.required],
      status: ['', Validators.required],
      condition_id: ['', Validators.required],
    });
    this.getTableData();
  }

  private getTableData(stat?:any): void {
    this.data.getDonationList(stat).subscribe((apiRes: any) => {
      this.tableData = [];
      apiRes.results.donations.forEach((res: donation, index: number) => {
        this.tableData.push({
          ...res,
        });
      });
    });
  }
  public viewDonation(data: donation): void {
    this.statusForm.reset();
    this.conditionsForm.reset();
    this.expandedIndex = null;
    this.singleDonation = data;
  }
  public updateStatusForm(data: donation): void {
    this.singleDonation = data;
    this.statusForm.patchValue({
      status: data.pickup_status,
    });
  }

  public onSubmitStatus(): void {
    if (this.statusForm.valid) {
      this.data
        .updateDonationStatus(
          this.singleDonation.donation_id,
          this.statusForm.value
        )
        .subscribe(
          (response) => {
            this.getTableData();
            // Reset form after submission
            this.statusForm.reset();
            // Close the modal using Bootstrap's API
            const modalElement = document.getElementById('update-status-modal');
            if (modalElement) {
              const modal = bootstrap.Modal.getInstance(modalElement);
              modal.hide();
            }
          },
          (error) => {
            console.error('Error creating user', error);
          }
        );
    }
  }
  public onSubmitCondition(): void {
    if (this.conditionsForm.valid) {
      if (this.expandedIndex !== null) {
        this.data
          .updateDonationCondition(
            this.singleDonation.donated_products[this.expandedIndex]
              .donated_product_id,
            this.conditionsForm.value
          )
          .subscribe(
            (response) => {
              this.getTableData();
              // Reset form after submission
              this.statusForm.reset();
              // Close the modal using Bootstrap's API
              const modalElement = document.getElementById(
                'product-details-modal'
              );
              if (modalElement) {
                const modal = bootstrap.Modal.getInstance(modalElement);
                modal.hide();
              }
            },
            (error) => {
              console.error('Error creating user', error);
            }
          );
      }
    }
  }

  onStatusChange(selectedStatus: string): void {
    const scheduledDateControl = this.statusForm.get('scheduled_date');
    // Clear values when hiding fields
    if (
      selectedStatus === 'Pickup Scheduled' ||
      selectedStatus === 'Pickup Pending Scheduling'
    ) {
      this.showScheduledDate = true;
      scheduledDateControl?.setValidators([Validators.required]);
    } else {
      scheduledDateControl?.clearValidators();
      scheduledDateControl?.setValue(''); // Reset value
    }
  }
  approveCondition(product: any) {
    product.product_condition_approval_status.user_condition.condition =
      product.newCondition;
    console.log('Approved Condition:', product.newCondition);
    alert(`Condition approved: ${product.newCondition}`);
  }
  public sortData(sort: Sort) {
    const data = this.tableData.slice();
    if (!sort.active || sort.direction === '') {
      this.tableData = data;
    } else {
      this.tableData = data.sort((a, b) => {
        const aValue = (a as never)[sort.active];
        const bValue = (b as never)[sort.active];
        return (aValue < bValue ? -1 : 1) * (sort.direction === 'asc' ? 1 : -1);
      });
    }
  }
  public toggleDetails(index: number) {
    this.expandedIndex = this.expandedIndex === index ? null : index;
    const subcategoryId =
      this.singleDonation.donated_products[index].product_details.subcategories
        .subcategory_id;
    this.data
      .getSubcategoryConditions(subcategoryId)
      .subscribe((apiRes: any) => {
        this.conditionOptions = apiRes.results;
        if (
          this.singleDonation.donated_products[index]
            .product_condition_approval_status.admin_condition != null
        ) {
          this.conditionsForm.patchValue({
            condition_id:
              this.singleDonation.donated_products[index]
                .product_condition_approval_status.admin_condition.
                condition_id,
            status:
              this.singleDonation.donated_products[index]
                .product_condition_approval_status.approval_status,
            description:
              this.singleDonation.donated_products[index].product_condition_approval_status
                .approval_status_description,
          });
        } else {
          this.conditionsForm.patchValue({
            status: 'PENDING',
          });
        }
      });
  }

  public filterRoles() : void{
    if (this.selectedPickupStatusFilter === 0) {
      this.getTableData();
    } else {
      this.getTableData(this.selectedPickupStatusFilter);
    }
  }

  public searchData(value: string): void {
    this.dataSource.filter = value.trim().toLowerCase();
    this.tableData = this.dataSource.filteredData;
  }
  isCollapsed: boolean = false;
  toggleCollapse() {
    this.sidebar.toggleCollapse();
    this.isCollapsed = !this.isCollapsed;
  }
  public filter = false;
  openFilter() {
    this.filter = !this.filter;
  }
  public cartValue = [2, 2, 2, 2, 2, 2, 2, 2];

  public addPos(i: number): void {
    this.cartValue[i]++;
  }
  public reducePos(i: number): void {
    this.cartValue[i]--;
  }
  selectAll(initChecked: boolean) {
    if (!initChecked) {
      this.tableData.forEach((f) => {
        f.isSelected = true;
      });
    } else {
      this.tableData.forEach((f) => {
        f.isSelected = false;
      });
    }
  }
}
